-- 세트 118: Redis 백업과 복원: RDB 스냅샷, AOF, 복원 순서
-- 기본기 사다리(docs/specs/spec_foundations_ladder.md). 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (118, 1, 'RDB 스냅샷을 만드는 두 가지 명령', 'Redis 의 데이터를 파일(RDB)로 저장하는 명령입니다. ① **지금 바로** 저장하지만 끝날 때까지 다른 명령을 막는 것, ② **백그라운드**에서 저장해 서비스에 영향을 줄이는 것입니다. 빈칸을 채우세요.', '이름이 그대로 save 와 bgsave(background save)예요.', NULL, NULL, '[]', 'fill', '["save", "bgsave", "flushall", "shutdown"]', NULL, '`SAVE` 는 저장이 끝날 때까지 서버가 멈추므로 운영에서는 피하고, 보통 `BGSAVE` 를 씁니다. 두 명령 모두 `dump.rdb` 를 만들어요. `FLUSHALL` 은 데이터를 지우는 명령이니 절대 헷갈리면 안 됩니다.', '[0, 1]', 'redis-cli {0}
redis-cli {1}', NULL, NULL),
  (118, 2, '장애로 직전 데이터가 사라졌어요', 'Redis 가 `save 900 1`(15분 안에 1건 이상 변경되면 저장) 같은 기본 RDB 설정만 쓰고 있었는데, 갑자기 서버가 꺼진 뒤 **마지막 몇 분간 쓴 데이터**가 사라졌습니다. 이유와 개선책으로 알맞은 것은 무엇일까요?', 'RDB 는 사진 찍듯 "주기적으로" 저장해요.', NULL, NULL, '[]', 'choice', '["Redis 는 원래 모든 데이터를 즉시 디스크에 저장하므로 이런 일은 없다", "메모리를 늘리면 해결된다", "RDB 는 일정 간격의 스냅샷이라 마지막 스냅샷 이후의 쓰기는 유실된다. 손실을 줄이려면 AOF(`appendonly yes`, `appendfsync everysec`)를 함께 쓴다", "키 이름을 짧게 바꾸면 해결된다"]', 2, 'RDB 는 가볍고 복원이 빠르지만 스냅샷 사이의 데이터는 보호하지 못합니다. AOF 는 쓰기 명령을 기록해 `everysec` 이면 최대 약 1초만 잃어요. 캐시라면 RDB 로 충분하지만 유실이 곤란한 데이터라면 AOF 를 고려하세요.', NULL, NULL, NULL, NULL),
  (118, 3, '복원하려고 파일을 덮어썼는데 데이터가 비어 있어요', 'Redis 가 **켜진 채로** `dump.rdb` 를 백업본으로 덮어쓰고 `redis-cli shutdown` 으로 껐다가 다시 켰더니 데이터가 비어 있습니다. 가장 알맞은 원인은 무엇일까요?', '정상 종료할 때 Redis 는 마지막으로 자기 메모리 상태를 저장할 수 있어요.', NULL, NULL, '[]', 'choice', '["종료 시 Redis 가 현재(복원 전) 메모리 상태를 `dump.rdb` 에 다시 저장해 백업본을 덮어썼다. 서버를 먼저 `shutdown nosave` 로 내린 뒤 파일을 교체해야 한다", "백업 파일이 너무 커서 읽을 수 없다", "Redis 는 복원을 지원하지 않는다", "파일 이름이 한글이라서 그렇다"]', 0, '복원의 순서는 **서버 중지(저장 없이) → 파일 교체 → 서버 시작** 입니다. 켜진 채로 파일만 바꾸면 Redis 는 그 사실을 모르고, 종료할 때 자기 메모리를 다시 써서 복원본을 지워 버려요.', NULL, NULL, NULL, NULL),
  (118, 4, '지금 상태를 백업 파일로 남기기', '실행 중인 Redis(저장 위치 `/tmp/r1`)에 키 5개가 있습니다. ① `redis-cli` 로 **스냅샷을 만들고**(서비스에 영향이 적은 방식 권장) ② 만들어진 `dump.rdb` 를 **`/tmp/backup.rdb`** 로 복사하세요. 마지막으로 파일이 정상인지 `redis-check-rdb` 로 검사해 보세요.', '`redis-cli bgsave` 는 백그라운드라 끝났는지 잠깐 기다려야 해서, 연습에서는 `redis-cli save` 로 해도 돼요. 복사는 `cp /tmp/r1/dump.rdb /tmp/backup.rdb`.', 'redis-cli save
cp /tmp/r1/dump.rdb /tmp/backup.rdb
redis-check-rdb /tmp/backup.rdb

# 스냅샷은 임시 파일에 쓴 뒤 이름을 바꾸므로 dump.rdb 를 복사해도 반쪽 파일이 되지 않는다. 그래도 복사본은 꼭 검사한다', '["sh", "-c", "rm -rf /tmp/r1 /tmp/backup.rdb && mkdir -p /tmp/r1 && redis-server --daemonize yes --dir /tmp/r1 --save '''' >/dev/null && sleep 1 && for i in 1 2 3 4 5; do redis-cli set user:$i v$i >/dev/null; done"]', '["sh", "-c", "( [ -s /tmp/backup.rdb ] ) && ( redis-check-rdb /tmp/backup.rdb >/dev/null 2>&1 ) && ( grep -aq user:3 /tmp/backup.rdb )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "backup.rdb 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/backup.rdb ]"]}, {"label": "redis-check-rdb 검사에 통과한다", "cmd": ["sh", "-c", "redis-check-rdb /tmp/backup.rdb >/dev/null 2>&1"]}, {"label": "백업에 user:3 키가 들어 있다", "cmd": ["sh", "-c", "grep -aq user:3 /tmp/backup.rdb"]}]', '[{"title": "Redis 영속성 문서", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/persistence/"}]'),
  (118, 5, 'RDB 파일로 복원하는 순서', '백업해 둔 RDB 로 Redis 를 복원합니다. 순서에 맞게 놓아 보세요.', '켜져 있을 때 파일을 바꾸면 안 돼요. 끈 다음 바꾸고, 켠 뒤 확인해요.', NULL, NULL, '[]', 'order', '["`redis-cli shutdown nosave` 로 서버를 저장 없이 내린다", "현재 `dump.rdb` 는 이름을 바꿔 따로 보관한다", "백업 파일을 `dump.rdb` 로 복사한다", "Redis 를 시작한다", "`dbsize` 와 대표 키로 복원됐는지 확인한다"]', NULL, '현재 파일을 지우지 않고 보관해 두면 복원이 잘못됐을 때 되돌릴 수 있습니다. 마지막 확인까지 해야 복원이 끝난 거예요.', '[0, 1, 2, 3, 4]', NULL, NULL, NULL),
  (118, 6, 'RDB 백업본으로 데이터 되살리기', '실수로 `FLUSHALL` 을 실행해 Redis(저장 위치 `/tmp/r2`)가 **텅 비었습니다.** 다행히 `/tmp/backup2.rdb` 에 5개 키가 든 백업이 있습니다. 서버를 **저장 없이** 내리고, 백업을 `dump.rdb` 로 되돌린 뒤 같은 위치로 다시 시작해 **키 5개를 복원**하세요.', '`redis-cli shutdown nosave` → `cp /tmp/backup2.rdb /tmp/r2/dump.rdb` → `redis-server --daemonize yes --dir /tmp/r2 --save ''''` 순서예요. 시작 후 잠깐(`sleep 1`) 기다려 `redis-cli dbsize` 로 확인하세요.', 'redis-cli shutdown nosave
cp /tmp/backup2.rdb /tmp/r2/dump.rdb
redis-server --daemonize yes --dir /tmp/r2 --save '''' >/dev/null
sleep 1
redis-cli dbsize
redis-cli get user:3

# 저장 없이(nosave) 내려야 비어 있는 현재 상태가 dump.rdb 를 덮어쓰지 않는다', '["sh", "-c", "rm -rf /tmp/r2 /tmp/backup2.rdb && mkdir -p /tmp/r2 && redis-server --daemonize yes --dir /tmp/r2 --save '''' >/dev/null && sleep 1 && for i in 1 2 3 4 5; do redis-cli set user:$i v$i >/dev/null; done && redis-cli save >/dev/null && cp /tmp/r2/dump.rdb /tmp/backup2.rdb && redis-cli flushall >/dev/null"]', '["sh", "-c", "( redis-cli ping | grep -q PONG ) && ( [ \\"$(redis-cli dbsize)\\" = \\"(integer) 5\\" ] || [ \\"$(redis-cli dbsize)\\" = 5 ] ) && ( [ \\"$(redis-cli get user:3)\\" = v3 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Redis 가 응답한다", "cmd": ["sh", "-c", "redis-cli ping | grep -q PONG"]}, {"label": "키가 5개이다", "cmd": ["sh", "-c", "[ \\"$(redis-cli dbsize)\\" = \\"(integer) 5\\" ] || [ \\"$(redis-cli dbsize)\\" = 5 ]"]}, {"label": "user:3 의 값이 복원됐다", "cmd": ["sh", "-c", "[ \\"$(redis-cli get user:3)\\" = v3 ]"]}]', '[{"title": "Redis 영속성 문서", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/persistence/"}]'),
  (118, 7, 'RDB 를 복원했는데 AOF 가 켜져 있어요', '`appendonly yes` 인 Redis 에서 RDB 백업을 `dump.rdb` 로 되돌리고 재시작했는데, 복원한 데이터가 보이지 않고 예전(비어 있는) 상태입니다. 가장 알맞은 설명은 무엇일까요?', '두 가지 저장 방식이 모두 있을 때 시작 시 읽는 쪽이 정해져 있어요.', NULL, NULL, '[]', 'choice', '["RDB 파일은 AOF 가 켜져 있으면 읽을 수 없는 형식이다", "재시작을 한 번 더 하면 자동으로 RDB 를 읽는다", "AOF 와 RDB 는 항상 같은 내용이다", "AOF 가 켜져 있으면 Redis 는 시작할 때 RDB 가 아니라 AOF 파일을 읽는다. RDB 복원 시에는 AOF 를 끄고 올리거나(복원 후 다시 켜기) AOF 파일도 함께 맞춰야 한다"]', 3, '둘 다 있으면 데이터가 더 완전한 AOF 를 우선합니다. 그래서 RDB 로만 되돌렸다면 AOF 가 비어 있는 상태가 그대로 올라와요. AOF 를 끈 채로 RDB 로 올린 뒤 `BGREWRITEAOF` 후 켜는 방식이 흔합니다.', NULL, NULL, NULL, NULL),
  (118, 8, '실행 중에 AOF 켜고 확인하기', '`/tmp/r3` 에서 실행 중인 Redis 는 AOF 가 꺼져 있습니다. 서버를 **재시작하지 않고** AOF 를 켜고, 키 `b` 를 하나 더 저장한 뒤 `/tmp/r3/appendonly.aof` 파일이 생겼고 그 안에 방금 쓴 `b` 가 기록됐는지 확인하세요. (확인 결과를 `/tmp/aof.txt` 에 저장)', '`redis-cli config set appendonly yes` 로 켜요. 파일이 만들어질 때까지 `sleep 2` 가 필요할 수 있어요. 확인은 `grep -a` 로 파일 안을 찾으면 돼요.', 'redis-cli config set appendonly yes
sleep 2
redis-cli set b 2
sleep 1
ls /tmp/r3
grep -a b /tmp/r3/appendonly.aof > /tmp/aof.txt
cat /tmp/aof.txt

# CONFIG SET 은 재시작하면 사라진다. 계속 쓰려면 redis.conf 에도 appendonly yes 를 적는다 (Redis 7 이상은 appendonlydir 폴더에 만들어진다)', '["sh", "-c", "rm -rf /tmp/r3 /tmp/aof.txt && mkdir -p /tmp/r3 && redis-server --daemonize yes --dir /tmp/r3 --save '''' >/dev/null && sleep 1 && redis-cli set a 1 >/dev/null"]', '["sh", "-c", "( [ \\"$(redis-cli config get appendonly | tail -n 1)\\" = yes ] ) && ( [ -s /tmp/r3/appendonly.aof ] ) && ( grep -aq b /tmp/r3/appendonly.aof ) && ( [ -s /tmp/aof.txt ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "AOF 가 켜져 있다", "cmd": ["sh", "-c", "[ \\"$(redis-cli config get appendonly | tail -n 1)\\" = yes ]"]}, {"label": "appendonly.aof 파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/r3/appendonly.aof ]"]}, {"label": "키 b 가 AOF 에 기록됐다", "cmd": ["sh", "-c", "grep -aq b /tmp/r3/appendonly.aof"]}, {"label": "확인 결과 파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/aof.txt ]"]}]', '[{"title": "Redis 영속성 문서", "url": "https://redis.io/docs/latest/operate/oss_and_stack/management/persistence/"}]'),
  (118, 9, 'redis.conf 에 AOF 설정 적기', 'AOF 를 **켜고**, **1초마다** 디스크에 기록(최대 약 1초 손실)하도록 `redis.conf` 의 빈칸을 채우세요.', '켜기는 yes, 1초마다는 everysec 이에요.', NULL, NULL, '[]', 'fill', '["yes", "everysec", "no", "always"]', NULL, '`appendfsync` 는 `always`(매 명령, 안전하지만 느림), `everysec`(1초마다, 보통의 선택), `no`(운영체제에 맡김) 중 고릅니다. `CONFIG SET` 으로 켠 것은 재시작 후 사라지므로 설정 파일에도 적어야 해요.', '[0, 1]', 'appendonly {0}
appendfsync {1}', NULL, NULL),
  (118, 10, '백업 파일을 믿기 전에', '매일 밤 `dump.rdb` 를 복사해 보관하고 있습니다. 어느 날 복원이 필요해졌는데 백업이 깨져 있으면 큰일입니다. 가장 알맞은 습관은 무엇일까요?', '"백업했다"와 "복원할 수 있다"는 다른 말이에요.', NULL, NULL, '[]', 'choice', '["백업 파일이 있으면 정상이라고 믿는다", "복사본을 `redis-check-rdb` 로 검사하고, 가끔 별도 인스턴스에 실제로 복원해 보는 리허설을 한다", "백업을 운영 서버 같은 디스크에만 둔다", "백업 파일 크기만 본다"]', 1, '파일이 있다는 것과 쓸 수 있다는 것은 다릅니다. `redis-check-rdb` 로 형식을 확인하고, 정기적으로 다른 곳에 복원해 보면 진짜 복원 가능한지 알 수 있어요. 백업은 서버 밖(다른 디스크·장소)에도 보관하세요.', NULL, NULL, NULL, NULL);
